// Red-team harness (SEC lane). Runs every page check the way packages/kit/README.md and kit.e2e.ts do
// (each check sent into the page as text), then grades. SEC_PAGE = path of an HTML file. SEC_WIDTH = window width (default 1280).
// Output goes to the file named by SEC_OUT (default sec-out.txt).
// SEC_WALK=1 adds { ruleId: 'behavior-dialog-keys', status: 'holds' } as kit.e2e.ts does for its "Crafted" test.
import { appendFileSync } from 'node:fs';
import { pathToFileURL } from 'node:url';
import { chromium } from 'playwright';
import { expect, it } from 'vitest';
import { KIT_RULES, grade, receipt, receiptText, repairPlan, type Finding } from '../../../packages/kit/src/index.js';
import * as checks from '../../../packages/kit/src/page-checks/index.js';

const TOKENS = { '--ink': '#1a1a1a', '--paper': '#ffffff', '--accent': '#0b5fff', '--line': '#d0d5dd', '--radius': '8px', '--radius-in': '4px', '--font-body': 'Georgia, serif' };
const say = (line: string): void => appendFileSync(process.env.SEC_OUT ?? 'sec-out.txt', line + '\n');
const CHECKS = checks as unknown as Record<string, (...args: never[]) => unknown>;

it('sec harness', async () => {
  const browser = await chromium.launch(process.env.PW_CHROMIUM ? { executablePath: process.env.PW_CHROMIUM } : {});
  const requests: string[] = [];
  const context = await browser.newContext({ viewport: { width: Number(process.env.SEC_WIDTH ?? 1280), height: 800 }, deviceScaleFactor: 1 });
  const page = await context.newPage();
  page.on('request', (r) => { if (!r.url().startsWith('file:')) requests.push(r.url()); });
  await page.goto(pathToFileURL(process.env.SEC_PAGE ?? '').href, { waitUntil: 'load' });
  await page.waitForTimeout(400);
  const only = process.env.SEC_ONLY ? process.env.SEC_ONLY.split(',') : Object.keys(CHECKS);
  const findings: Finding[] = [];
  const limit = Number(process.env.SEC_LIMIT_MS ?? 60000);
  for (const fn of only) {
    const started = Date.now();
    const source = `(${String(CHECKS[fn])})(document${fn === 'tokenFit' ? `, ${(process.env.SEC_TOKENS ?? JSON.stringify(TOKENS))}` : ''})`;
    const result = await Promise.race([
      (page.evaluate(source) as Promise<Finding[]>).catch((e: unknown) => `THREW: ${String(e).split('\n')[0]}`),
      new Promise<string>((resolve) => setTimeout(() => resolve(`NO ANSWER after ${limit} ms`), limit)),
    ]);
    const ms = Date.now() - started;
    if (typeof result === 'string') { say(`CHECK ${fn}: ${result} (${ms} ms)`); if (result.startsWith('NO ANSWER')) break; continue; }
    if (ms > 2000) say(`CHECK ${fn}: took ${ms} ms`);
    findings.push(...result);
  }
  if (process.env.SEC_WALK === '1') findings.push({ ruleId: 'behavior-dialog-keys', status: 'holds' });
  const g = grade(findings, KIT_RULES);
  say('FAILS: ' + JSON.stringify(findings.filter((f) => f.status === 'fails').map((f) => `${f.ruleId} @ ${f.where ?? ''} : ${f.measured ?? ''}`)));
  say('STATUS: ' + findings.filter((f) => f.status !== 'fails').map((f) => `${f.ruleId}=${f.status}`).join(' '));
  say('GRADE: ' + JSON.stringify(g));
  say('NETWORK: ' + JSON.stringify(requests));
  if (process.env.SEC_RECEIPT === '1') say('RECEIPT:\n' + receiptText(receipt(findings, KIT_RULES)));
  if (process.env.SEC_PLAN === '1') say('PLAN: ' + JSON.stringify(repairPlan([findings], KIT_RULES), null, 1));
  await browser.close().catch(() => undefined);
  expect(true).toBe(true);
}, 600_000);
